/* EHR › Billing (Figma 1857:144674): billing records + refunds lists, invoice pop-up per status, refund pop-up per status, manual refund with searchable patient picker,
   record payment, and the printable invoice (paid / awaiting / failed / cancelled). */
(function () {
  const { esc, acts, ins, chs } = App; const PT = App.PT;
  const meta = { key: 'billing', icon: 'ri-money-pound-circle-line', title: 'Billing' };
  const chip = (t, tone, i) => `<span class="chip sm filled ${tone}">${i ? `<i class="${i}"></i>` : ''}${esc(t)}</span>`;
  const keep = () => { const y = scrollY; App.render(); scrollTo(0, y); };
  const money = n => '£' + Number(n).toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  const stamp = () => '22/10/2026, ' + new Date().toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' });
  const IS = { 'Awaiting Payment': ['t-orange', 'ri-time-line'], 'Payment Complete': ['t-green', 'ri-checkbox-circle-line'], 'Payment Failed': ['t-red', 'ri-close-circle-line'], Cancelled: ['t-grey', 'ri-forbid-line'], 'Part Paid': ['t-blue', 'ri-pie-chart-2-line'], 'Refund applicable': ['t-purple', 'ri-refund-2-line'] };
  const RS = { Pending: ['t-orange', 'ri-time-line'], Refunded: ['t-green', 'ri-checkbox-circle-line'], Failed: ['t-red', 'ri-close-circle-line'], Rejected: ['t-grey', 'ri-forbid-line'] };
  const SV = [['Aesthetics Consultation', 'Service', 80], ['Weight Management Programme', 'Package', 199], ['Follow-up Consultation', 'Service', 45], ['Blood Test Panel', 'Service', 85], ['GLP-1 Monthly Package', 'Package', 199], ['Initial Assessment', 'Service', 65], ['Botox Treatment', 'Service', 220]];
  const EXTRA = [['Ahmad Khan', '2003-08-22', 'ahmad.khan@email.com', '020 7123 4567', '24 Maple Street, Manchester', 'M14 5PQ'], ['Lotfi Ladjemi', '1988-02-11', 'lotfi.l@email.com', '07700 900 812', '45 Fosse Road North, Leicester', 'LE3 5RR'], ['Grace Okafor', '1992-09-10', 'grace.okafor@email.com', '07700 900 441', '8 Elm Row, London', 'N1 7QP']];
  const S = App.S;
  const people = () => [...S.patients.map(p => ({ id: p.id, name: PT.name(p), dob: p.dob, email: p.email, phone: p.phone, addr: `${p.addr}, ${p.city}`, pc: p.postcode, eth: p.eth })), ...EXTRA.map(([name, dob, email, phone, addr, pc], i) => ({ id: 'x' + i, name, dob, email, phone, addr, pc, eth: 'White British' }))];
  const who = id => people().find(p => p.id === id);
  const STAFF = ['Dr Sana Bashir', 'Dr Sarah Mitchell', 'Dr Olivia Brown', 'Nurse Tom Reid'];
  if (!S.inv2) { const pp = people(), st = ['Payment Complete', 'Awaiting Payment', 'Payment Complete', 'Payment Failed', 'Payment Complete', 'Cancelled', 'Awaiting Payment', 'Payment Complete'];
    S.inv2 = Array.from({ length: 26 }, (_, i) => { const s = SV[i % SV.length], status = st[i % st.length], d = new Date(2026, 9, 20 - i * 2), appt = new Date(d.getTime() + 7 * 864e5); appt.setHours(9 + (i % 7), i % 2 ? 30 : 0);
      const v = { id: 'HC-' + (3502 + i), pid: pp[i % pp.length].id, svc: s[0], kind: s[1], amt: s[2], status, issued: d, appt, ref: 'APT-' + (2045 + i), clin: STAFF[i % STAFF.length], method: i % 3 === 2 ? 'Bank transfer' : 'Card', pays: [], log: [['Payment link sent to patient', d, '']] };
      if (status === 'Payment Complete') { v.pays.push({ amt: v.amt, method: v.method, at: d }); v.log.push([`Payment recorded via ${v.method.toLowerCase()}`, new Date(d.getTime() + 18 * 6e4), '']); }
      if (status === 'Payment Failed') v.log.push(['Card payment declined — insufficient funds', new Date(d.getTime() + 20 * 6e4), '']);
      if (status === 'Cancelled') { v.cancelled = new Date(d.getTime() + 864e5); v.why = i % 2 ? 'Cancelled by patient' : 'Cancelled by the clinic · clinician unavailable'; v.log.push([v.why, v.cancelled, '']); }
      return v; });
    const paid = S.inv2.filter(v => v.status === 'Payment Complete');
    S.ref2 = paid.slice(0, 9).map((v, i) => ({ id: 'RF-' + (1201 + i), inv: v.id, amt: i % 3 === 1 ? Math.round(v.amt / 2) : v.amt, type: ['Clinic Cancellation', 'Patient Cancellation', 'Clinician Did Not Attend', 'Goodwill'][i % 4], mode: i % 3 === 0 ? 'Manual' : 'Automatic', status: ['Pending', 'Refunded', 'Refunded', 'Failed', 'Pending', 'Refunded', 'Rejected', 'Refunded', 'Pending'][i], by: i % 3 === 0 ? 'Muhammad Arslan' : 'System', at: new Date(2026, 9, 18 - i * 2, 10, 12), log: [] }));
    S.ref2.forEach(r => { r.log.push([`Refund ${r.mode === 'Manual' ? 'manually' : 'automatically'} initiated`, r.at, r.by]); if (r.status === 'Refunded') r.log.push(['Payment refunded successfully', new Date(r.at.getTime() + 18 * 6e4), '']); if (r.status === 'Failed') r.log.push(['Refund failed — card no longer active', new Date(r.at.getTime() + 18 * 6e4), '']); if (r.status === 'Rejected') r.log.push(['Refund rejected — outside the refund window', new Date(r.at.getTime() + 864e5), 'Muhammad Arslan']); }); }
  const I = S.inv2, R = S.ref2, inv = id => I.find(v => v.id === id), ref = id => R.find(r => r.id === id);
  const dd = d => d.toLocaleDateString('en-GB'), dl = d => d.toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric' }), dt = d => `${dd(d)}, ${d.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' })}`;
  const apptTxt = d => `${d.toLocaleDateString('en-GB', { weekday: 'short', day: 'numeric', month: 'short' })}, ${d.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' })}`;
  const paidOf = v => v.pays.reduce((n, p) => n + p.amt, 0), refundedOf = v => R.filter(r => r.inv === v.id && r.status !== 'Rejected' && r.status !== 'Failed').reduce((n, r) => n + r.amt, 0);
  const f = App.ui.bill = { tab: 'records', q: '', status: 'All', kind: 'All', rq: '', rstatus: 'All', rmode: 'All', rtype: 'All', page: 0 };

  /* ---------- frame ---------- */
  const tile = (icon, tone, t, sub, amt) => `<div class="bl-tile"><span class="bl-ic ${tone}"><i class="${icon}"></i></span><div class="grow"><b>${t}</b><small>${sub}</small></div><span class="bl-amt">${money(amt)}</span></div>`;
  const frame = (tab, body) => `<nav class="crumbs" aria-label="Breadcrumb"><a href="#/billing">Billing</a><span>/</span><span class="cur">${tab === 'records' ? 'Billing Records' : 'Refunds'}</span></nav>
    <div class="pt-seg">${[['records', 'Billing Records', '#/billing'], ['refunds', 'Refunds', '#/billing/refunds']].map(([k, t, h]) => `<button class="${k === tab ? 'on' : ''}" data-go="${h}">${t}</button>`).join('')}</div>${body}`;
  const pager = (n, p) => `<div class="pager"><span class="tnum">${n ? `${p * 10 + 1}–${Math.min(n, p * 10 + 10)} of ${n}` : '0 of 0'}</span><span class="row g4"><button class="icon-btn s20" data-act="bl-pg" data-v="-1" ${p ? '' : 'disabled'} aria-label="Previous page"><i class="ri-arrow-left-s-line"></i></button><button class="icon-btn s20" data-act="bl-pg" data-v="1" ${p * 10 + 10 < n ? '' : 'disabled'} aria-label="Next page"><i class="ri-arrow-right-s-line"></i></button></span></div>`;
  acts['bl-pg'] = el => { f.page += +el.dataset.v; keep(); };

  /* ---------- billing records ---------- */
  App.route('/billing', () => { const out = I.filter(v => ['Awaiting Payment', 'Payment Failed', 'Part Paid'].includes(v.status)), done = I.filter(v => v.status === 'Payment Complete'), rf = R.filter(r => r.status === 'Refunded');
    const q = f.q.toLowerCase(), l = I.filter(v => (f.status === 'All' || v.status === f.status) && (f.kind === 'All' || v.kind === f.kind) && (!q || (v.id + who(v.pid).name + v.svc + v.ref).toLowerCase().includes(q)));
    return frame('records', `<div class="bl-tiles">${tile('ri-time-line', 'orange', 'Outstanding Payments', `${out.length} invoices awaiting payment`, out.reduce((n, v) => n + v.amt - paidOf(v), 0))}${tile('ri-check-line', 'green', 'Complete Payments', `${done.length} invoices paid`, done.reduce((n, v) => n + v.amt, 0))}${tile('ri-refund-2-line', 'teal', 'Refunds', `${rf.length} refunds`, rf.reduce((n, r) => n + r.amt, 0))}</div>
      <section class="card card-pad stack g16"><div class="pt-bar"><h1 class="h6 hh1" style="margin:0">All Billing Records</h1><span class="grow"></span><button class="btn primary" data-act="bl-new-refund"><i class="ri-refund-2-line"></i>Initiate Manual Refund</button></div>
      <div class="filters">${App.field('Search', `<span class="adorn"><i class="ri-search-line"></i></span><input data-in="bl-q" value="${esc(f.q)}" placeholder="Invoice, patient, service or reference">`, { cls: 'search' })}${App.select('Payment Status', 'bl-f', ['All', ...Object.keys(IS)], f.status, { attrs: 'data-k="status"' })}${App.select('Service / Package', 'bl-f', ['All', 'Service', 'Package'], f.kind, { attrs: 'data-k="kind"' })}<button class="clear-btn" data-act="bl-clear"><i class="ri-close-line"></i>Clear filters</button></div>
      <div class="table-card"><div class="table-scroll"><table class="dt"><thead><tr><th>Invoice ID</th><th>Patient Name</th><th>Service</th><th>Appointment Reference</th><th>Payment Status</th><th>Amount</th><th>Issued <i class="ri-arrow-down-line"></i></th><th>Actions</th></tr></thead><tbody>${l.slice(f.page * 10, f.page * 10 + 10).map(v => `<tr><td class="fw5">${v.id}</td><td>${who(v.pid).id.startsWith('p') ? `<a class="brand-u" href="#/patients/${v.pid}">${esc(who(v.pid).name)}</a>` : esc(who(v.pid).name)}</td><td>${esc(v.svc)}<small class="cell-sub">${v.kind}</small></td><td><a class="brand-u" href="#/appointments">${v.ref}</a><small class="cell-sub">${apptTxt(v.appt)}</small></td><td>${chip(v.status, ...IS[v.status])}${refundedOf(v) ? `<small class="cell-sub">${money(refundedOf(v))} refunded</small>` : ''}</td><td class="tnum">${money(v.amt)}</td><td>${dd(v.issued)}</td>
        <td><span class="row-actions"><button class="icon-btn s20" data-act="bl-pdf" data-id="${v.id}" aria-label="Download invoice ${v.id}" title="Download PDF"><i class="ri-download-2-line"></i></button><button class="icon-btn s20" data-act="bl-inv" data-id="${v.id}" aria-label="View invoice ${v.id}" title="View"><i class="ri-eye-line"></i></button></span></td></tr>`).join('') || '<tr class="empty-row"><td colspan="8">No invoices match. <button class="btn text brand sm" data-act="bl-clear">Clear filters</button></td></tr>'}</tbody></table></div>${pager(l.length, f.page)}</div></section>`); }, meta);
  ins['bl-q'] = el => { f.q = el.value; f.page = 0; keep(); const n = App.$('[data-in=bl-q]'); n.focus(); n.setSelectionRange(n.value.length, n.value.length); };
  chs['bl-f'] = el => { f[el.dataset.k] = el.value; f.page = 0; keep(); };
  acts['bl-clear'] = () => { Object.assign(f, { q: '', status: 'All', kind: 'All', rq: '', rstatus: 'All', rmode: 'All', rtype: 'All', page: 0 }); App.render(); };

  /* ---------- refunds ---------- */
  App.route('/billing/refunds', () => { const q = f.rq.toLowerCase(), l = R.filter(r => { const v = inv(r.inv); return (f.rstatus === 'All' || r.status === f.rstatus) && (f.rmode === 'All' || r.mode === f.rmode) && (f.rtype === 'All' || r.type === f.rtype) && (!q || (r.id + v.id + who(v.pid).name + v.svc).toLowerCase().includes(q)); });
    const done = R.filter(r => r.status === 'Refunded'), sum = a => a.reduce((n, r) => n + r.amt, 0);
    return frame('refunds', `<div class="bl-tiles">${tile('ri-refund-2-line', 'teal', 'Total Refunds', `${done.length} refunds processed`, sum(done))}${tile('ri-robot-2-line', 'teal', 'Automatic Refunds', `${done.filter(r => r.mode === 'Automatic').length} automatic refunds`, sum(done.filter(r => r.mode === 'Automatic')))}${tile('ri-user-settings-line', 'teal', 'Manual Refunds', `${done.filter(r => r.mode === 'Manual').length} manual refunds`, sum(done.filter(r => r.mode === 'Manual')))}</div>
      <section class="card card-pad stack g16"><div class="pt-bar"><h1 class="h6 hh1" style="margin:0">Manage Refunds</h1><span class="grow"></span><button class="btn primary" data-act="bl-new-refund"><i class="ri-add-line"></i>Initiate Manual Refund</button></div>
      <div class="filters">${App.field('Search', `<span class="adorn"><i class="ri-search-line"></i></span><input data-in="bl-rq" value="${esc(f.rq)}" placeholder="Refund, invoice or patient">`, { cls: 'search' })}${App.select('Refund Status', 'bl-f', ['All', ...Object.keys(RS)], f.rstatus, { attrs: 'data-k="rstatus"' })}${App.select('Initiated', 'bl-f', ['All', 'Automatic', 'Manual'], f.rmode, { attrs: 'data-k="rmode"' })}${App.select('Refund Type', 'bl-f', ['All', 'Clinic Cancellation', 'Patient Cancellation', 'Clinician Did Not Attend', 'Goodwill'], f.rtype, { attrs: 'data-k="rtype"' })}<button class="clear-btn" data-act="bl-clear"><i class="ri-close-line"></i>Clear filters</button></div>
      <div class="table-card"><div class="table-scroll"><table class="dt"><thead><tr><th>Invoice ID</th><th>Patient Name</th><th>Service</th><th>Appointment Reference</th><th>Refund Type</th><th>Amount</th><th>Refund Status</th><th>Actions</th></tr></thead><tbody>${l.map(r => { const v = inv(r.inv); return `<tr><td class="fw5">${v.id}<small class="cell-sub">${r.id}</small></td><td>${esc(who(v.pid).name)}</td><td>${esc(v.svc)}</td><td><a class="brand-u" href="#/appointments">${v.ref}</a></td><td>${chip(r.mode, r.mode === 'Manual' ? 't-purple' : 't-blue')}<small class="cell-sub">${r.type}</small></td><td class="tnum">${money(r.amt)}</td><td>${chip(r.status, ...RS[r.status])}</td>
        <td><span class="row-actions"><button class="icon-btn s20" data-act="bl-pdf" data-id="${v.id}" aria-label="Download" title="Download"><i class="ri-download-2-line"></i></button><button class="icon-btn s20" data-act="bl-ref" data-id="${r.id}" aria-label="View refund ${r.id}" title="View"><i class="ri-eye-line"></i></button>${r.status === 'Pending' ? `<button class="btn outlined sm" data-act="bl-ref" data-id="${r.id}">Review</button>` : ''}</span></td></tr>`; }).join('') || '<tr class="empty-row"><td colspan="8">No refunds match. <button class="btn text brand sm" data-act="bl-clear">Clear filters</button></td></tr>'}</tbody></table></div></div></section>`); }, meta);
  ins['bl-rq'] = el => { f.rq = el.value; keep(); const n = App.$('[data-in=bl-rq]'); n.focus(); n.setSelectionRange(n.value.length, n.value.length); };

  /* ---------- shared pop-up pieces ---------- */
  const head = (t, st, sub) => `<div class="bl-dh"><span class="bl-dic"><i class="ri-file-text-line"></i></span><div class="grow"><div class="row g8 wrap"><h2 id="dlg-title">${t}</h2>${st}</div><small>${sub}</small></div><button class="icon-btn s20" data-act="close-modal" aria-label="Close"><i class="ri-close-line"></i></button></div>`;
  const kv = rows => `<dl class="bl-kv">${rows.map(([k, x]) => `<div><dt>${k}</dt><dd>${x}</dd></div>`).join('')}</dl>`;
  const timeline = log => `<h3 class="bl-h3"><i class="ri-time-line"></i>Activity Timeline</h3><ol class="bl-tl">${log.map(([t, at, by]) => `<li><b>${esc(t)}</b><small>${dt(at)}${by ? ` by ${esc(by)}` : ''}</small></li>`).join('')}</ol>`;
  const linked = v => v.rx ? `<a class="brand-u" href="#/patients/${v.pid}/prescriptions/${v.rx}" data-act="close-modal">Prescription ${esc(v.rx)}</a><small>${apptTxt(v.appt)}</small>`
    : `<a class="brand-u" href="#/appointments" data-act="close-modal">${esc(v.svc)}</a><small>${apptTxt(v.appt)}</small>`;

  /* ---------- invoice pop-up ---------- */
  const invModal = v => { const p = who(v.pid), due = v.amt - paidOf(v), rf = refundedOf(v);
    const actions = { 'Awaiting Payment': `<div class="g2" style="gap:8px"><button class="btn outlined" data-act="bl-copy" data-id="${v.id}"><i class="ri-link"></i>Copy payment link</button><button class="btn outlined" data-act="bl-resend" data-id="${v.id}"><i class="ri-send-plane-line"></i>Resend link</button></div><button class="btn primary lg block" data-act="bl-pay" data-id="${v.id}">Record Payment</button><div class="row g16" style="justify-content:center"><button class="btn text sm" data-act="bl-pdf" data-id="${v.id}">Download PDF</button><button class="btn text sm" style="color:var(--error)" data-act="bl-cancel" data-id="${v.id}">Cancel invoice</button></div>`,
      'Payment Failed': `<div class="pt-warn"><i class="ri-error-warning-line"></i><span>The patient’s card was declined. Send the link again or take payment another way.</span></div><div class="g2" style="gap:8px"><button class="btn outlined" data-act="bl-resend" data-id="${v.id}"><i class="ri-send-plane-line"></i>Resend link</button><button class="btn primary" data-act="bl-pay" data-id="${v.id}">Record Payment</button></div>`,
      'Part Paid': `<button class="btn primary lg block" data-act="bl-pay" data-id="${v.id}">Record Payment</button>`,
      'Payment Complete': `<div class="row g12"><button class="btn primary" data-act="bl-pdf" data-id="${v.id}"><i class="ri-download-2-line"></i>Download PDF</button>${rf < v.amt ? `<button class="btn text brand" data-act="bl-new-refund" data-id="${v.id}">Issue refund</button>` : ''}</div>`,
      'Refund applicable': `<div class="pt-warn"><i class="ri-refund-2-line"></i><span><b>Refund applicable</b>The prescription was cancelled after it was paid for. Nothing has been refunded yet.</span></div><div class="row g12"><button class="btn primary" data-act="bl-new-refund" data-id="${v.id}"><i class="ri-refund-2-line"></i>Start refund</button><a class="btn text brand" href="#/patients/${v.pid}/prescriptions/${v.rx}" data-act="close-modal">View prescription</a></div>`,
      Cancelled: `<div class="row g12"><button class="btn primary" data-act="bl-pdf" data-id="${v.id}"><i class="ri-download-2-line"></i>Download PDF</button><a class="btn text brand" href="${v.rx ? `#/patients/${v.pid}/prescriptions/${v.rx}` : '#/appointments'}" data-act="close-modal">${v.rx ? 'View prescription' : 'View appointment'}</a></div>` }[v.status];
    App.dialog(`<div class="bl-dlg">${head('Invoice ' + v.id, chip(v.status, ...IS[v.status]), 'Issued ' + dl(v.issued))}<div class="bl-logo"><b>Leaf</b><span>Ease</span><i class="ri-leaf-line"></i></div>
      <div class="bl-box">${kv([['Patient Name', esc(p.name)], [v.rx ? 'Reference' : 'Appointment Reference', v.ref], [v.rx ? 'Linked prescription' : 'Linked appointment', linked(v)], ['Clinician', esc(v.clin)], ['Service / Package', `${esc(v.svc)} · ${v.kind}`], ['Payment Method', v.method], ['Status', chip(v.status, ...IS[v.status])]])}</div>
      <div class="bl-total"><span>Total Cost</span><b>${money(v.amt)}</b></div>${paidOf(v) && v.status !== 'Payment Complete' ? `<div class="row between caption"><span>Paid so far</span><span>${money(paidOf(v))} · <b class="warn">${money(due)} outstanding</b></span></div>` : ''}${rf ? `<div class="row between caption"><span>Refunded</span><span>−${money(rf)}</span></div>` : ''}
      ${timeline(v.log)}<div class="stack g8">${actions}</div></div>`, { width: 480 }); };
  acts['bl-inv'] = el => invModal(inv(el.dataset.id));
  acts['bl-copy'] = el => { try { navigator.clipboard.writeText(`https://pay.leafease.co.uk/i/${el.dataset.id}`)?.catch?.(() => {}); } catch (e) {} App.snack('Payment link copied.'); };
  acts['bl-resend'] = el => { const v = inv(el.dataset.id); v.log.push(['Payment link resent to patient', new Date(), 'Muhammad Arslan']); if (v.status === 'Payment Failed') v.status = 'Awaiting Payment'; invModal(v); keep(); App.snack(`Payment link resent to ${who(v.pid).email}.`); };
  acts['bl-pdf'] = el => { App.closeModal(); App.go('#/billing/invoice/' + el.dataset.id); scrollTo(0, 0); };
  acts['bl-cancel'] = el => { const v = inv(el.dataset.id);
    App.dialog(PT.modal('ri-forbid-line', 'Cancel invoice?', `${v.id} · ${esc(who(v.pid).name)} · ${money(v.amt)}`, PT.F('Reason', 'why', '', { req: true, area: true, ph: 'e.g. Clinician unavailable, appointment released' }) + '<div class="pt-note"><i class="ri-information-line"></i>The patient is told no payment is due. The cancelled invoice is kept for records.</div>', `<button class="btn outlined lg" data-act="bl-inv" data-id="${v.id}">Keep invoice</button><button class="btn danger lg" data-act="bl-cancel-go" data-id="${v.id}">Cancel invoice</button>`, 'red'), { width: 460 }); };
  acts['bl-cancel-go'] = el => { const d = PT.formData(); if (!PT.needs(d, ['why'])) return; const v = inv(el.dataset.id); Object.assign(v, { status: 'Cancelled', cancelled: new Date(), why: 'Cancelled by the clinic · ' + d.why }); v.log.push(['Invoice cancelled by the clinic', new Date(), 'Muhammad Arslan']); invModal(v); keep(); App.snack(`${v.id} cancelled.`); };

  /* ---------- record payment ---------- */
  let pm = 'Card terminal';
  acts['bl-pay'] = el => { const v = inv(el.dataset.id), due = v.amt - paidOf(v); pm = 'Card terminal';
    App.dialog(PT.modal('ri-bank-card-line', 'Record Payment', `Invoice ${v.id} · ${esc(who(v.pid).name)}`, `<div class="bl-box">${kv([['Linked appointment', linked(v)], ['Service / Package', v.kind], ['Status', chip(v.status, ...IS[v.status])]])}<div class="bl-total" style="margin-top:8px"><span>Outstanding</span><b>${money(due)}</b></div></div><b class="sub2">Payment Method</b>
      <div class="row g8 wrap" id="bl-pm">${['Card terminal', 'Cash', 'Bank transfer', 'Online payment'].map(m => `<button type="button" class="chip-btn ${m === pm ? 'on' : ''}" data-act="bl-pm" data-v="${m}">${m}</button>`).join('')}</div><div class="g2">${PT.F('Amount paid (£)', 'amt', due.toFixed(2), { req: true, type: 'number', step: '0.01' })}${PT.F('Payment date', 'date', '2026-10-22', { req: true, type: 'date' })}</div>${PT.F('Notes (optional)', 'note', '', { area: true, ph: 'e.g. Paid on WorldPay terminal, ref 8841' })}<div class="pt-note"><i class="ri-information-line"></i>Partial amounts are fine — the rest stays outstanding on the invoice.</div>`,
      `<button class="btn outlined lg" data-act="bl-inv" data-id="${v.id}">Cancel</button><button class="btn primary lg" data-act="bl-pay-go" data-id="${v.id}" id="bl-pay-btn">Record ${money(due)} Paid</button>`, 'green'), { width: 500 });
    App.$('#pt-form [name=amt]').addEventListener('input', e => { App.$('#bl-pay-btn').textContent = `Record ${money(+e.target.value || 0)} Paid`; }); };
  acts['bl-pm'] = el => { pm = el.dataset.v; App.$$('#bl-pm .chip-btn').forEach(b => b.classList.toggle('on', b === el)); };
  acts['bl-pay-go'] = el => { const d = PT.formData(), v = inv(el.dataset.id), due = v.amt - paidOf(v), amt = +d.amt;
    if (!(amt > 0)) return App.snack('Enter the amount paid.', 'error'); if (amt > due + .001) return App.snack(`That’s more than the ${money(due)} outstanding.`, 'error');
    v.pays.push({ amt, method: pm, at: new Date() }); v.method = pm === 'Card terminal' || pm === 'Online payment' ? 'Card' : pm; v.status = amt >= due ? 'Payment Complete' : 'Part Paid'; v.log.push([`Payment of ${money(amt)} recorded via ${pm.toLowerCase()}`, new Date(), 'Muhammad Arslan']);
    invModal(v); keep(); App.snack(v.status === 'Payment Complete' ? `${v.id} is paid in full.` : `${money(amt)} recorded. ${money(due - amt)} still outstanding.`); };

  /* ---------- refund pop-up ---------- */
  const refModal = r => { const v = inv(r.inv), p = who(v.pid), age = Math.floor((new Date(2026, 9, 22) - new Date(p.dob)) / 31557600000);
    const banner = { Failed: `<div class="bl-ban red"><i class="ri-close-circle-line"></i><div><b>Refund failed</b><span>${esc(r.log[r.log.length - 1][0])}. Retry, or void the invoice and settle another way.</span></div></div>`, Rejected: `<div class="bl-ban grey"><i class="ri-forbid-line"></i><div><b>Refund rejected</b><span>${esc(r.why || 'Outside the refund window.')}</span></div></div>`, Refunded: `<div class="bl-ban green"><i class="ri-checkbox-circle-line"></i><div><b>Refund complete</b><span>${money(r.amt)} returned to the patient’s ${v.method.toLowerCase()}. It can take 5–10 working days to appear.</span></div></div>` }[r.status] || '';
    const actions = { Pending: `<div class="pt-dlg-foot"><button class="btn outlined lg" data-act="bl-ref-reject" data-id="${r.id}"><i class="ri-close-line"></i>Reject Refund</button><button class="btn primary lg" data-act="bl-ref-approve" data-id="${r.id}">Approve Refund</button></div>`, Failed: `<div class="pt-dlg-foot"><button class="btn outlined lg" style="color:var(--error);border-color:rgba(211,47,47,.5)" data-act="bl-void" data-id="${r.id}"><i class="ri-close-line"></i>Void Invoice</button><button class="btn primary lg" data-act="bl-ref-retry" data-id="${r.id}"><i class="ri-refresh-line"></i>Retry Refund</button></div>`, Refunded: `<button class="btn outlined" data-act="bl-pdf" data-id="${v.id}"><i class="ri-download-2-line"></i>Download receipt</button>`, Rejected: '' }[r.status];
    App.dialog(`<div class="bl-dlg">${head('Refund Details', chip(r.status, ...RS[r.status]), `Initiated ${r.mode === 'Manual' ? 'manually' : 'automatically'} on ${dt(r.at)}`)}${banner}
      <div class="bl-box"><h3 class="bl-h3"><i class="ri-file-text-line"></i>Refund Information</h3>${kv([['Patient Name', esc(p.name)], ['Refund Type', r.type], ['Invoice', v.id], [v.rx ? 'Reference' : 'Appointment Reference', v.ref], [v.rx ? 'Linked prescription' : 'Linked appointment', linked(v)], ['Service / Package', `${esc(v.svc)} · ${v.kind}`], ['Payment Method', v.method], ['Status', chip(r.status, ...RS[r.status])]])}</div>
      <div class="bl-box"><h3 class="bl-h3"><i class="ri-user-line"></i>Patient Details</h3>${kv([['Date of birth', `${dd(new Date(p.dob))} (Age: ${age})`], ['Ethnicity', esc(p.eth || '—')], ['Email', esc(p.email)], ['Phone Number', esc(p.phone)], ['Address', esc(p.addr)], ['Post Code', esc(p.pc)]])}</div>
      <div class="bl-total"><span>Total Refund Amount</span><b>${money(r.amt)}</b></div>${r.note ? `<p class="caption" style="margin:0"><b>Note:</b> ${esc(r.note)}</p>` : ''}${timeline(r.log)}${actions}</div>`, { width: 500 }); };
  acts['bl-ref'] = el => refModal(ref(el.dataset.id));
  acts['bl-ref-approve'] = el => { const r = ref(el.dataset.id); r.status = 'Refunded'; r.log.push(['Refund approved', new Date(), 'Muhammad Arslan'], ['Payment refunded successfully', new Date(), '']); refModal(r); keep(); App.snack(`${money(r.amt)} refunded to ${who(inv(r.inv).pid).name}.`); };
  acts['bl-ref-reject'] = el => { const r = ref(el.dataset.id);
    App.dialog(PT.modal('ri-close-circle-line', 'Reject refund?', `${r.id} · ${money(r.amt)}`, PT.F('Reason', 'why', '', { req: true, area: true, ph: 'The patient sees this reason in their email' }), `<button class="btn outlined lg" data-act="bl-ref" data-id="${r.id}">Back</button><button class="btn danger lg" data-act="bl-ref-reject-go" data-id="${r.id}">Reject Refund</button>`, 'red'), { width: 460 }); };
  acts['bl-ref-reject-go'] = el => { const d = PT.formData(); if (!PT.needs(d, ['why'])) return; const r = ref(el.dataset.id); r.status = 'Rejected'; r.why = d.why; r.log.push(['Refund rejected — ' + d.why, new Date(), 'Muhammad Arslan']); refModal(r); keep(); App.snack('Refund rejected. The patient has been emailed the reason.'); };
  acts['bl-ref-retry'] = el => { const r = ref(el.dataset.id); r.status = 'Pending'; r.log.push(['Refund retried', new Date(), 'Muhammad Arslan']); refModal(r); keep(); App.snack('Refund resubmitted — it’s back in Pending.'); };
  acts['bl-void'] = el => { const r = ref(el.dataset.id), v = inv(r.inv); Object.assign(v, { status: 'Cancelled', cancelled: new Date(), why: 'Voided after a failed refund' }); v.log.push(['Invoice voided after failed refund', new Date(), 'Muhammad Arslan']); r.status = 'Rejected'; r.why = 'Invoice voided — settle outside the system'; r.log.push(['Invoice voided', new Date(), 'Muhammad Arslan']); refModal(r); keep(); App.snack(`${v.id} voided.`); };

  /* ---------- initiate manual refund (searchable patient picker) ---------- */
  let M = null;
  acts['bl-new-refund'] = el => { const v = el.dataset.id ? inv(el.dataset.id) : null; M = { pid: v ? v.pid : '', inv: v ? v.id : '', q: '' }; drawM(); };
  const paidInv = pid => I.filter(v => v.pid === pid && paidOf(v) > refundedOf(v));
  const drawM = () => { const p = M.pid && who(M.pid), list = p ? paidInv(p.id) : [], v = M.inv && inv(M.inv), max = v ? paidOf(v) - refundedOf(v) : 0;
    App.dialog(`<div class="bl-dlg">${head('Initiate Manual Refund', '', 'Raise a refund on behalf of a patient')}<b class="sub2">Request Details</b><form class="stack g12" id="pt-form" onsubmit="return false">
      <div class="field select bl-pp ${M.err && !p ? 'err' : ''}"><label>Patient <b>*</b></label><button type="button" class="pt-staff-btn" data-act="bl-pp" data-menu-anchor aria-haspopup="listbox">${p ? `${esc(p.name)} <small class="caption">· ${esc(p.email)}</small>` : 'Search and select a patient'}</button></div>
      ${App.field('Invoice', `<select name="inv" data-ch="bl-mi" ${p ? '' : 'disabled'}><option value="">${p ? (list.length ? 'Select a paid invoice' : 'No paid invoices for this patient') : 'Choose a patient first'}</option>${list.map(x => `<option value="${x.id}" ${x.id === M.inv ? 'selected' : ''}>${x.id} · ${esc(x.svc)} · ${money(paidOf(x) - refundedOf(x))}</option>`).join('')}</select>`, { req: true, cls: 'select' + (p ? '' : ' dis') + (M.err && !v ? ' err' : '') })}
      ${App.field('Refund Type', `<select name="type">${['Clinic Cancellation', 'Patient Cancellation', 'Clinician Did Not Attend', 'Goodwill'].map(t => `<option>${t}</option>`).join('')}</select>`, { req: true, cls: 'select' })}
      <div class="stack g4">${PT.F('Refund Amount (£)', 'amt', v ? max.toFixed(2) : '', { req: true, type: 'number', step: '0.01' })}${v ? `<span class="caption" style="margin:0 12px">Up to ${money(max)} can be refunded on ${v.id}.</span>` : ''}</div>
      ${App.field('Refund Method', `<select name="method"><option>Original payment method</option><option>Bank transfer</option><option>Cash</option></select>`, { cls: 'select' })}${PT.F('Reason', 'note', '', { req: true, area: true, ph: 'Shown to the patient in their refund email' })}</form>
      <div class="pt-note"><i class="ri-information-line"></i>The patient is told the refund amount and reason by email.</div><div class="pt-dlg-foot"><button class="btn outlined lg" data-act="close-modal">Cancel</button><button class="btn primary lg" data-act="bl-m-go">Initiate Refund</button></div></div>`, { width: 500 }); };
  acts['bl-pp'] = el => { const rows = q => people().filter(p => !q || (p.name + p.email + p.phone).toLowerCase().includes(q.toLowerCase())).slice(0, 8).map(p => `<button data-pick="${p.id}" class="pt-staff-row ${p.id === M.pid ? 'on' : ''}"><span><b>${esc(p.name)}</b> <small>${esc(p.email)}</small></span><small>${paidInv(p.id).length} paid</small></button>`).join('') || '<div class="caption" style="padding:12px">No patients match.</div>';
    App.menu(el, `<div class="pt-staff-menu"><div class="field sm"><input placeholder="Search patient by name, email or phone…" aria-label="Search patients"><span class="adorn"><i class="ri-search-line"></i></span></div><div class="pt-staff-list">${rows('')}</div></div>`, v2 => { M.pid = v2; M.inv = ''; drawM(); }, { width: el.offsetWidth + 28, alignLeft: true, onSearch: (q, m) => { m.querySelector('.pt-staff-list').innerHTML = rows(q); } }); };
  chs['bl-mi'] = el => { M.inv = el.value; drawM(); };
  acts['bl-m-go'] = () => { const d = PT.formData(); M.err = true; if (!M.pid || !M.inv) { drawM(); return App.snack('Choose the patient and the invoice to refund.', 'error'); } if (!PT.needs(d, ['amt', 'note'])) return;
    const v = inv(M.inv), max = paidOf(v) - refundedOf(v), amt = +d.amt; if (!(amt > 0) || amt > max + .001) return App.snack(`Enter an amount up to ${money(max)}.`, 'error');
    const r = { id: 'RF-' + (1201 + R.length), inv: v.id, amt, type: d.type, mode: 'Manual', status: 'Pending', by: 'Muhammad Arslan', at: new Date(), note: d.note, log: [['Refund manually initiated', new Date(), 'Muhammad Arslan']] }; R.unshift(r);
    v.log.push([`Manual refund of ${money(amt)} initiated`, new Date(), 'Muhammad Arslan']);
    if (v.status === 'Refund applicable') { v.status = 'Cancelled'; v.cancelled = v.cancelled || new Date(); v.why = v.why || `Prescription ${v.rx} cancelled · refund ${r.id} initiated`; } M = null; f.tab = 'refunds'; App.go('#/billing/refunds'); refModal(r); App.snack(`Refund ${r.id} created — approve it to send the money.`); };

  /* ---------- printable invoice ---------- */
  App.route('/billing/invoice/:id', id => { const v = inv(id); if (!v) return '<section class="soon"><h1 class="soon-h1">Invoice not found</h1></section>'; const p = who(v.pid), paid = v.status === 'Payment Complete', cancel = v.status === 'Cancelled', failed = v.status === 'Payment Failed', due14 = new Date(v.issued.getTime() + 14 * 864e5);
    const tag = paid ? ['PAID IN FULL', 'green'] : cancel ? ['CANCELLED', 'red'] : failed ? ['PAYMENT FAILED', 'red'] : ['AWAITING PAYMENT', 'orange'];
    return `<div class="bl-print-bar"><a class="btn outlined sm pt-dark" href="#/billing"><i class="ri-arrow-left-s-line"></i>Back to Billing</a><span class="grow"></span><button class="btn primary sm" onclick="print()"><i class="ri-printer-line"></i>Print / Save as PDF</button></div>
    <article class="bl-pdf">${cancel ? '<div class="bl-wm" aria-hidden="true">CANCELLED</div>' : ''}<header><div><div class="bl-logo plain"><b>Leaf</b><span>Ease</span><i class="ri-leaf-line"></i></div><b>LeafEase Clinic Ltd</b><small>12 Granby Street, Leicester LE1 1DE</small><small>+44 116 496 0100 · billing@leafease.co.uk</small><small>Company No. 09876543</small></div><div class="bl-pdf-r"><h1>INVOICE</h1><span>${v.id}</span><em class="${tag[1]}">${tag[0]}</em></div></header>
      <div class="bl-meta">${[['Invoice number', v.id], ['Issue date', dl(v.issued)], [paid ? 'Payment date' : cancel ? 'Cancelled on' : 'Due date', paid ? dl(v.pays[0].at) : cancel ? dl(v.cancelled) : dl(due14), cancel || (!paid) ? 'red' : ''], ['Amount due', paid || cancel ? '£0.00' : money(v.amt - paidOf(v)), !paid && !cancel ? 'red' : '']].map(([k, x, c]) => `<div><small>${k}</small><b class="${c || ''}">${x}</b></div>`).join('')}</div>
      ${cancel ? `<div class="bl-pban red"><b>This invoice has been cancelled, no payment is due</b><span>${esc(v.why)} on ${dl(v.cancelled)}. The appointment has been released. No payment was taken.</span></div>` : ''}
      <div class="bl-two"><div><small>Billed to</small><b>${esc(p.name)}</b><span>${esc(p.addr)}, ${esc(p.pc)}, United Kingdom</span><span>${esc(p.email)} · ${esc(p.phone)}</span></div><div><small>Appointment</small><b>${esc(v.svc)}</b><span>Reference · ${v.ref}</span><span>${apptTxt(v.appt)} · Leicester site</span><span>Clinician · ${esc(v.clin)}</span></div></div>
      <table class="bl-lines"><thead><tr><th>Description</th><th>Qty</th><th>Unit price</th><th>Amount</th></tr></thead><tbody><tr><td><b>${esc(v.svc)}${v.kind === 'Service' ? ' (30 min)' : ''}</b><small>${v.kind === 'Package' ? 'Programme package' : 'Consultation and treatment plan'}</small></td><td>1</td><td>${money(v.amt)}</td><td>${money(v.amt)}</td></tr></tbody></table>
      <div class="bl-sum"><div class="bl-tot"><span>Total</span><b>${money(v.amt)}</b></div>${paid ? `<div class="row between"><span>Paid ${dl(v.pays[0].at)}</span><span>−${money(v.amt)}</span></div>` : cancel ? `<div class="row between"><span>Cancelled ${dl(v.cancelled)}</span><span>−${money(v.amt)}</span></div>` : `<div class="row between"><b>Balance due</b><b class="red">${money(v.amt - paidOf(v))}</b></div>`}</div>
      ${paid ? `<div class="bl-pban green"><div class="row between"><b>Paid in full, thank you</b><b>${money(v.amt)}</b></div><span>${v.method === 'Card' ? 'Card ending 4242' : v.method} · Transaction TXN-${88213 + I.indexOf(v)} · ${dt(v.pays[0].at)}</span></div>`
        : cancel ? `<div class="bl-pban grey"><div class="row between"><b>Nothing to pay</b><b>£0.00</b></div><span>This document is kept for your records. A replacement invoice is issued if the appointment is rebooked.</span></div>`
        : `<div class="bl-pban orange"><div class="row between"><b>${failed ? 'Your last payment didn’t go through' : 'How to pay'}</b><span>Due by ${dl(due14)}</span></div><div class="bl-two"><div><b>Pay by card</b><span>Open the secure payment link sent to ${esc(p.email)}, or call the clinic on +44 116 496 0100.</span></div><div><b>Bank transfer</b><span>LeafEase Clinic Ltd · Sort code 04-00-04 · Account 12345678 · Reference ${v.id}</span></div></div></div>`}
      <footer><small>NOTES &amp; TERMS</small><p>Payment terms: 14 days from the issue date. Appointments cancelled with less than 24 hours’ notice may be charged in full. Questions about this invoice? Email billing@leafease.co.uk quoting ${v.id}.</p><div class="row between"><span>LeafEase Clinic Ltd · Registered in England &amp; Wales No. 09876543 · Computer-generated invoice, valid without signature.</span><span>Page 1 of 1</span></div></footer></article>`; }, { public: true, key: 'billing', icon: '', title: 'Invoice' });
})();
